using System.Globalization;
using System.Text;
using Microsoft.CodeAnalysis;
using Sunder.Package.Build.Rpc.Authoring;
using Sunder.Package.Build.Rpc.Authoring.CSharp;
using Sunder.Sdk.Rpc;

namespace Sunder.Package.Build.Authoring;

internal static class SunderPackageCompositionEmitter
{
    internal static SunderRpcCSharpSourceFile EmitApp(SunderPackageAuthoringAnalysis analysis)
    {
        RequireValid(analysis);
        var output = new StringBuilder("""
            // <auto-generated />
            #nullable enable
            using global::Microsoft.Extensions.DependencyInjection;
            using global::Microsoft.Extensions.DependencyInjection.Extensions;
            using global::Sunder.Sdk.Avalonia;
            namespace Sunder.Generated.Package;
            public sealed class AppModule : global::Sunder.Sdk.Abstractions.ISunderAppPackageModule
            {
                public void ConfigureAppServices(IServiceCollection services, global::Sunder.Sdk.Abstractions.IPackageContext context)
                {
            """);
        output.AppendLine();
        EmitBindingLifetime(output);
        EmitImportedApis(output, analysis, "app");
        foreach (var contract in analysis.Compilation.Contracts)
        {
            if (SunderRpcAuthoringDocuments.ResolveAppUse(contract.Exposure, contract.Descriptor, contract.AppUse) is null) continue;
            var api = SunderRpcCSharpServiceApiEmitter.ApiType(contract);
            var client = SunderRpcCSharpServiceApiEmitter.RemoteType(contract);
            output.Append("        services.TryAddSingleton<").Append(api).Append(", ").Append(client).AppendLine(">();");
            EmitCatalogRegistration(output, api, SunderRpcCSharpServiceApiEmitter.CatalogType(contract));
        }
        foreach (var entry in analysis.Composition!.App)
        {
            var view = analysis.RolePlan.Views.SingleOrDefault(view => view.MetadataName == Type(entry.Type));
            output.Append("        services.TryAdd").Append(entry.Transient ? "Transient" : "Singleton").Append('<').Append(Type(entry.Type)).Append(">(dependencies => ");
            if (view?.ViewModelMetadataName is null) output.Append(Construct(entry)).AppendLine(");");
            else output.Append("{ var viewModel = dependencies.GetRequiredService<").Append(view.ViewModelMetadataName)
                .Append(">(); var view = ").Append(Construct(entry, view.ViewModelMetadataName))
                .AppendLine("; view.DataContext = viewModel; return view; });");
        }
        output.AppendLine("    }")
            .AppendLine("    public void RegisterAppContributions(global::Sunder.Sdk.Abstractions.ISunderAppContributionRegistry registry, global::System.IServiceProvider services)")
            .AppendLine("    {");
        foreach (var view in analysis.RolePlan.Views)
        {
            if (view.IsSettings) output.Append("        registry.RegisterSettingsView<").Append(view.MetadataName).AppendLine(">();");
            else output.Append("        registry.RegisterPackageView<").Append(view.MetadataName).Append(">(new global::Sunder.Sdk.Abstractions.PackageViewRegistration(")
                .Append(Literal(view.ViewId!)).Append(", ").Append(Literal(view.DisplayName!)).Append(", ").Append(view.IconPath is null ? "null" : Literal(view.IconPath))
                .Append(", (global::Sunder.Sdk.Abstractions.PackageViewPlacement)").Append(view.DefaultPlacement).AppendLine("));");
        }
        output.AppendLine("    }").AppendLine("}");
        return new("app-module.g.cs", output.ToString());
    }

    internal static SunderRpcCSharpSourceFile EmitWorker(SunderPackageAuthoringAnalysis analysis)
    {
        RequireValid(analysis);
        var output = new StringBuilder("""
            // <auto-generated />
            #nullable enable
            using global::Microsoft.Extensions.DependencyInjection;
            using global::Microsoft.Extensions.DependencyInjection.Extensions;
            namespace Sunder.Generated.Package {
            internal static class WorkerEntryPoint
            {
                public static global::System.Threading.Tasks.Task Main()
                    => global::Sunder.Sdk.Worker.SunderWorker.RunAsync(Create);
                internal static global::Sunder.Sdk.Worker.SunderWorkerOptions Create(global::Sunder.Sdk.Worker.SunderWorkerContext context)
                    => Create(context, context.Rpc);
                internal static global::Sunder.Sdk.Worker.SunderWorkerOptions Create(global::Sunder.Sdk.Abstractions.IPackageContext context, global::Sunder.Sdk.Rpc.ISunderRpcClient rpc)
                {
                    var services = new ServiceCollection();
                    services.AddSingleton<global::Sunder.Sdk.Abstractions.IPackageContext>(context);
                    services.AddSingleton<global::Sunder.Sdk.Rpc.ISunderRpcClient>(rpc);
            """);
        output.AppendLine();
        EmitBindingLifetime(output);
        var providers = analysis.Compilation.Contracts.SelectMany(contract => contract.Providers)
            .Concat(analysis.Compilation.ImportedProviders.Select(value => value.Provider))
            .OrderBy(value => value.ProviderId, StringComparer.Ordinal).ToArray();
        EmitImportedApis(output, analysis, "runtime");
        foreach (var entry in analysis.Composition!.Worker)
            output.Append("        services.TryAddSingleton<").Append(Type(entry.Type)).Append(">(dependencies => ").Append(Construct(entry)).AppendLine(");");
        foreach (var contract in analysis.Compilation.Contracts)
        {
            if (contract.RuntimeUse is not null)
                EmitCatalogRegistration(output, SunderRpcCSharpServiceApiEmitter.ApiType(contract), SunderRpcCSharpServiceApiEmitter.CatalogType(contract));
            var remote = contract.ServiceType.TypeKind == TypeKind.Interface || SunderRpcCSharpServiceApiEmitter.RequiresContext(contract);
            if (remote && contract.RuntimeUse is null) continue;
            var api = SunderRpcCSharpServiceApiEmitter.ApiType(contract);
            var local = contract.ServiceType.TypeKind == TypeKind.Class && SunderRpcCSharpServiceApiEmitter.HasLocalMethods(contract);
            if (!local)
                output.Append("        services.TryAddSingleton<").Append(api).Append(", ").Append(SunderRpcCSharpServiceApiEmitter.RemoteType(contract)).AppendLine(">();");
            else
            {
                if (remote) output.Append("        services.TryAddSingleton<").Append(SunderRpcCSharpServiceApiEmitter.RemoteType(contract)).AppendLine(">();");
                output.Append("        services.TryAddSingleton<").Append(api).Append(">(dependencies => new ").Append(SunderRpcCSharpServiceApiEmitter.LocalType(contract))
                    .Append("(dependencies.GetRequiredService<").Append(Type(contract.ServiceType)).Append(">()");
                if (remote) output.Append(", dependencies.GetRequiredService<").Append(SunderRpcCSharpServiceApiEmitter.RemoteType(contract)).Append(">()");
                output.AppendLine("));");
            }
        }
        output.AppendLine("        var provider = services.BuildServiceProvider(new ServiceProviderOptions { ValidateOnBuild = true, ValidateScopes = true });")
            .AppendLine("        try {")
            .AppendLine("        var registrations = new global::System.Collections.Generic.List<global::Sunder.Sdk.Worker.SunderWorkerProviderRegistration>();");
        foreach (var item in providers)
            output.Append("        registrations.Add(").Append(Type(item.SourceType)).Append('.').Append(item.DeclarationFactory).Append("(new DeferredHandler(() => provider.GetRequiredService<")
                .Append(Type(item.SourceType)).Append(">().").Append(item.ServicesFactory).AppendLine("(rpc, provider).Handler)));");
        output.AppendLine("        return new(registrations) {");
        var settings = analysis.Composition.Worker.SingleOrDefault(entry => SunderPackageDependencyDiscovery.IsSettingsSchemaProvider(entry.Type));
        if (settings is not null)
            output.Append("            SettingsSchema = ((global::Sunder.Sdk.Worker.ISunderWorkerSettingsSchemaProvider)provider.GetRequiredService<")
                .Append(Type(settings.Type)).AppendLine(">()).SettingsSchema,");
        var migrations = analysis.Composition.Worker.SingleOrDefault(entry => SunderPackageDependencyDiscovery.IsStorageMigrationProvider(entry.Type));
        if (migrations is not null)
        {
            foreach (var property in new[] { "StateMigrations", "SecretMigrations" })
                output.Append("            ").Append(property).Append(" = ((global::Sunder.Sdk.Worker.ISunderWorkerStorageMigrationProvider)provider.GetRequiredService<")
                    .Append(Type(migrations.Type)).Append(">()).").Append(property).AppendLine(",");
        }
        var preparations = analysis.Composition.Worker.Where(entry => SunderPackageDependencyDiscovery.IsStorageMigrationPreparation(entry.Type)).ToArray();
        if (preparations.Length != 0)
        {
            output.AppendLine("            OnBeforeStorageMigrations = async (preparation, token) => {");
            foreach (var preparation in preparations)
                output.Append("                token.ThrowIfCancellationRequested(); await ((global::Sunder.Sdk.Worker.ISunderWorkerStorageMigrationPreparation)provider.GetRequiredService<")
                    .Append(Type(preparation.Type)).AppendLine(">()).PrepareStorageMigrationsAsync(preparation, token).ConfigureAwait(false);");
            output.AppendLine("            },");
        }
        var auth = analysis.Composition.Worker.SingleOrDefault(entry => SunderPackageDependencyDiscovery.IsAuthHandler(entry.Type));
        var callbacks = analysis.Composition.Worker.Where(entry => SunderPackageDependencyDiscovery.IsCallbackHandler(entry.Type)
            && !SunderPackageDependencyDiscovery.IsAuthHandler(entry.Type)).ToArray();
        if (auth is not null)
            output.Append("            AuthHandler = provider.GetRequiredService<").Append(Type(auth.Type)).AppendLine(">(),");
        if (callbacks.Length != 0)
        {
            output.AppendLine("            CallbackHandlers = new global::Sunder.Sdk.Abstractions.IPackageCallbackHandler[] {");
            foreach (var callback in callbacks)
                output.Append("                provider.GetRequiredService<").Append(Type(callback.Type)).AppendLine(">(),");
            output.AppendLine("            },");
        }
        var lifecycle = analysis.Composition.Worker.Where(entry => entry.Lifecycle).ToArray();
        var activation = analysis.Composition.Worker.Where(entry => entry.Activation).ToArray();
        var staged = lifecycle.Length != 0 || auth is not null || callbacks.Length != 0;
        if (staged)
        {
            output.AppendLine("            Composition = new global::Sunder.Sdk.Worker.SunderWorkerComposition(provider, new global::Sunder.Sdk.Worker.ISunderWorkerLifecycleService[] {");
            foreach (var entry in analysis.Composition.Worker.Where(entry => entry.Lifecycle || entry.Activation))
                output.Append("            new ").Append(entry.Lifecycle ? "DeferredLifecycle<" : "DeferredActivation<").Append(Type(entry.Type))
                    .Append(">(() => provider.GetRequiredService<").Append(Type(entry.Type)).AppendLine(">()),");
            output.AppendLine("        }),");
        }
        else
        {
            // Owning ordinary DI does not require background-service or Runtime
            // generation capabilities. Lifecycle and host-routed callback roots use
            // the SDK composition to own their activation-scoped service provider.
            output.AppendLine("            OnShutdown = new ServiceLifetime(provider).ShutdownAsync,");
            if (activation.Length != 0)
            {
                output.AppendLine("            OnActivated = async (context, token) => {");
                foreach (var entry in activation)
                    output.Append("                token.ThrowIfCancellationRequested(); await ((global::Sunder.Sdk.Worker.ISunderWorkerActivationService)provider.GetRequiredService<")
                        .Append(Type(entry.Type)).AppendLine(">()).ActivateAsync(context, token).ConfigureAwait(false);");
                output.AppendLine("            },");
            }
        }
        output.AppendLine("        };")
            .AppendLine("        } catch { provider.DisposeAsync().AsTask().GetAwaiter().GetResult(); throw; }")
            .AppendLine("    }")
            .AppendLine("    private sealed class DeferredHandler(global::System.Func<global::Sunder.Sdk.Rpc.ISunderRpcServiceHandler> factory) : global::Sunder.Sdk.Rpc.ISunderRpcServiceHandler")
            .AppendLine("    {")
            .AppendLine("        private readonly global::System.Lazy<global::Sunder.Sdk.Rpc.ISunderRpcServiceHandler> _handler = new(factory);")
            .AppendLine("        public global::System.Threading.Tasks.ValueTask<global::System.Text.Json.JsonElement> InvokeUnaryAsync(global::Sunder.Sdk.Rpc.SunderRpcInvocationContext context, string serviceId, string methodId, global::System.Text.Json.JsonElement request, global::System.Threading.CancellationToken token = default)")
            .AppendLine("            => _handler.Value.InvokeUnaryAsync(context, serviceId, methodId, request, token);")
            .AppendLine("        public global::System.Collections.Generic.IAsyncEnumerable<global::System.Text.Json.JsonElement> InvokeServerStreamAsync(global::Sunder.Sdk.Rpc.SunderRpcInvocationContext context, string serviceId, string methodId, global::System.Text.Json.JsonElement request, global::System.Threading.CancellationToken token = default)")
            .AppendLine("            => _handler.Value.InvokeServerStreamAsync(context, serviceId, methodId, request, token);")
            .AppendLine("    }");
        if (staged)
        {
            if (lifecycle.Length != 0)
                output.AppendLine("    private sealed class DeferredLifecycle<T>(global::System.Func<T> factory) : global::Sunder.Sdk.Worker.ISunderWorkerLifecycleService where T : global::Sunder.Sdk.Worker.ISunderWorkerLifecycleService")
            .AppendLine("    {")
            .AppendLine("        private readonly global::System.Lazy<T> _service = new(factory);")
            .AppendLine("        public global::System.Threading.Tasks.Task Completion => _service.Value.Completion;")
            .AppendLine("        public global::System.Threading.Tasks.ValueTask PrepareCandidateAsync(global::System.Threading.CancellationToken token = default) => _service.Value.PrepareCandidateAsync(token);")
            .AppendLine("        public global::System.Threading.Tasks.ValueTask CommitGenerationAsync(global::Sunder.Sdk.Worker.SunderWorkerGenerationContext context, global::System.Threading.CancellationToken token = default) => _service.Value.CommitGenerationAsync(context, token);")
            .AppendLine("        public global::System.Threading.Tasks.ValueTask ActivateAsync(global::Sunder.Sdk.Worker.SunderWorkerContext context, global::System.Threading.CancellationToken token = default) => _service.Value.ActivateAsync(context, token);")
            .AppendLine("        public global::System.Threading.Tasks.ValueTask ShutdownAsync(global::Sunder.Sdk.Worker.SunderWorkerShutdownContext context, global::System.Threading.CancellationToken token = default) => _service.Value.ShutdownAsync(context, token);")
            .AppendLine("    }");
            if (activation.Length != 0)
                output.AppendLine("""
                        private sealed class DeferredActivation<T>(global::System.Func<T> factory) : global::Sunder.Sdk.Worker.ISunderWorkerLifecycleService where T : global::Sunder.Sdk.Worker.ISunderWorkerActivationService
                        {
                            private readonly global::System.Lazy<T> _service = new(factory);
                            public global::System.Threading.Tasks.Task Completion => global::System.Threading.Tasks.Task.CompletedTask;
                            public global::System.Threading.Tasks.ValueTask PrepareCandidateAsync(global::System.Threading.CancellationToken token = default)
                            { token.ThrowIfCancellationRequested(); _ = _service.Value; return global::System.Threading.Tasks.ValueTask.CompletedTask; }
                            public global::System.Threading.Tasks.ValueTask CommitGenerationAsync(global::Sunder.Sdk.Worker.SunderWorkerGenerationContext context, global::System.Threading.CancellationToken token = default)
                            { token.ThrowIfCancellationRequested(); return global::System.Threading.Tasks.ValueTask.CompletedTask; }
                            public global::System.Threading.Tasks.ValueTask ActivateAsync(global::Sunder.Sdk.Worker.SunderWorkerContext context, global::System.Threading.CancellationToken token = default) => _service.Value.ActivateAsync(context, token);
                            public global::System.Threading.Tasks.ValueTask ShutdownAsync(global::Sunder.Sdk.Worker.SunderWorkerShutdownContext context, global::System.Threading.CancellationToken token = default) => global::System.Threading.Tasks.ValueTask.CompletedTask;
                        }
                    """);
        }
        else
            output.AppendLine("""
                    private sealed class ServiceLifetime(global::Microsoft.Extensions.DependencyInjection.ServiceProvider services)
                    {
                        internal global::Microsoft.Extensions.DependencyInjection.ServiceProvider Services { get; } = services;
                        private readonly object _gate = new();
                        private global::System.Threading.Tasks.Task? _shutdown;
                        internal global::System.Threading.Tasks.ValueTask ShutdownAsync(global::Sunder.Sdk.Worker.SunderWorkerShutdownContext context, global::System.Threading.CancellationToken token)
                        {
                            global::System.Threading.Tasks.TaskCompletionSource completion;
                            lock (_gate)
                            {
                                if (_shutdown is not null) return new(_shutdown);
                                completion = new(global::System.Threading.Tasks.TaskCreationOptions.RunContinuationsAsynchronously);
                                _shutdown = completion.Task;
                            }
                            _ = DisposeAsync(completion);
                            return new(completion.Task);
                        }
                        private async global::System.Threading.Tasks.Task DisposeAsync(global::System.Threading.Tasks.TaskCompletionSource completion)
                        {
                            try { await Services.DisposeAsync().ConfigureAwait(false); completion.TrySetResult(); }
                            catch (global::System.Exception error) { completion.TrySetException(error); }
                        }
                    }
                """);
        output.AppendLine("}").AppendLine("}")
            .Append(SunderRpcCSharpServiceApiEmitter.EmitLocalServices(analysis.Compilation.Contracts));
        return new("worker-entry.g.cs", output.ToString());
    }

    internal static IReadOnlyList<SunderRpcCSharpSourceFile> EmitWorkerClients(SunderPackageAuthoringAnalysis analysis, string packageId, string packageVersion)
    {
        RequireValid(analysis);
        var contracts = analysis.Compilation.Contracts.Where(contract => contract.RuntimeUse is not null).ToArray();
        return contracts.Length == 0 ? [] : SunderRpcCSharpServiceApiEmitter.EmitAppClients(contracts, packageId, packageVersion, providerSchemasPresent: true);
    }

    private static void EmitImportedApis(StringBuilder output, SunderPackageAuthoringAnalysis analysis, string role)
    {
        foreach (var api in analysis.Compilation.ImportedPackageApis.Where(api => api.ConsumerRoles.Contains(role, StringComparer.Ordinal)))
            output.Append("        services.TryAddSingleton<global::").Append(api.InterfaceMetadataName).Append(", global::")
                .Append(api.ImplementationMetadataName).AppendLine(">();");
        foreach (var service in analysis.Compilation.ImportedPackageApis.Where(api => api.ConsumerRoles.Contains(role, StringComparer.Ordinal))
                     .SelectMany(api => api.Services).Concat(role == "runtime" ? analysis.Compilation.ImportedUses.Select(use => use.Service) : [])
                     .DistinctBy(service => service.InterfaceMetadataName).OrderBy(service => service.InterfaceMetadataName, StringComparer.Ordinal))
            EmitCatalogRegistration(output, "global::" + service.InterfaceMetadataName, "global::" + service.CatalogMetadataName);
    }

    private static void EmitCatalogRegistration(StringBuilder output, string api, string implementation)
    {
        var catalog = SunderRpcCSharpServiceApiEmitter.CatalogApiType(api);
        var factory = SunderRpcCSharpServiceApiEmitter.ReferenceFactoryApiType(api);
        output.Append("        services.TryAddSingleton<").Append(catalog).Append(", ").Append(implementation).AppendLine(">();")
            .Append("        services.TryAddSingleton<").Append(factory).Append(">(dependencies => ((").Append(implementation)
            .Append(")dependencies.GetRequiredService<").Append(catalog).AppendLine(">()).BindExact);");
    }

    private static void EmitBindingLifetime(StringBuilder output)
        => output.AppendLine("        services.TryAddSingleton<global::Sunder.Sdk.Rpc.SunderRpcServiceBindingLifetime>();");

    private static string Construct(SunderPackageServiceConstruction entry, string? viewModelType = null)
        => "new " + Type(entry.Type) + "(" + string.Join(", ", entry.Constructor.Parameters.Select(parameter =>
        {
            var type = parameter.Type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
            var binding = entry.Arguments.SingleOrDefault(argument => SymbolEqualityComparer.Default.Equals(argument.Parameter, parameter));
            var value = binding is null ? DefaultArgument(parameter)
                : binding.ServiceType.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat) == viewModelType
                    ? "viewModel" : "dependencies.GetRequiredService<" + binding.ServiceType.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat) + ">()";
            if (binding?.Deferred == true)
            {
                var requested = ((INamedTypeSymbol)parameter.Type).TypeArguments[0].ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
                value = "new global::System.Lazy<" + requested + ">(() => (" + requested + ")(" + value + "))";
            }
            // Preserve the selected overload, including interface bindings and
            // optional defaults. Omission or a concrete argument can pick another ctor.
            return SunderRpcCSharpSyntax.EscapeIdentifier(parameter.Name) + ": (" + type + ")(" + value + ")";
        })) + ")";

    private static string DefaultArgument(IParameterSymbol parameter)
    {
        if (!parameter.HasExplicitDefaultValue) throw new InvalidOperationException("The validated constructor parameter has no binding or default.");
        return parameter.ExplicitDefaultValue switch
        {
            null => "default(" + parameter.Type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat) + ")!",
            string value => Microsoft.CodeAnalysis.CSharp.SymbolDisplay.FormatLiteral(value, quote: true),
            char value => Microsoft.CodeAnalysis.CSharp.SymbolDisplay.FormatLiteral(value, quote: true),
            bool value => value ? "true" : "false",
            uint value => value.ToString(CultureInfo.InvariantCulture) + "U",
            long value => value.ToString(CultureInfo.InvariantCulture) + "L",
            ulong value => value.ToString(CultureInfo.InvariantCulture) + "UL",
            decimal value => value.ToString(CultureInfo.InvariantCulture) + "M",
            float value when float.IsNaN(value) => "global::System.Single.NaN",
            float value when float.IsPositiveInfinity(value) => "global::System.Single.PositiveInfinity",
            float value when float.IsNegativeInfinity(value) => "global::System.Single.NegativeInfinity",
            float value => value.ToString("R", CultureInfo.InvariantCulture) + "F",
            double value when double.IsNaN(value) => "global::System.Double.NaN",
            double value when double.IsPositiveInfinity(value) => "global::System.Double.PositiveInfinity",
            double value when double.IsNegativeInfinity(value) => "global::System.Double.NegativeInfinity",
            double value => value.ToString("R", CultureInfo.InvariantCulture) + "D",
            sbyte or byte or short or ushort or int => Convert.ToString(parameter.ExplicitDefaultValue, CultureInfo.InvariantCulture)!,
            _ => throw new InvalidOperationException("The constructor default is not a supported C# constant."),
        };
    }
    private static string Type(INamedTypeSymbol type) => type.ToDisplayString(SymbolDisplayFormat.FullyQualifiedFormat);
    private static string Literal(string value) => Microsoft.CodeAnalysis.CSharp.SymbolDisplay.FormatLiteral(value, quote: true);
    private static void RequireValid(SunderPackageAuthoringAnalysis analysis)
    {
        ArgumentNullException.ThrowIfNull(analysis);
        if (!analysis.Success || analysis.Composition is null) throw new InvalidOperationException("Composition requires a validated package analysis and constructor plan.");
    }
}
